# SPDX-License-Identifier: Apache-2.0
#
# Linker version script for libv8malloc.so. A single SONAME-aligned
# version node holds every exported symbol; new symbols are added to
# the same node within a major release. A new node (V8MALLOC_2.0, etc.)
# is introduced only on a major bump.

V8MALLOC_1.0 {
	global:
		v8m_version;
		v8m_version_major;
		v8m_version_minor;
		v8m_version_patch;

		v8m_malloc;
		v8m_free;
		v8m_calloc;
		v8m_realloc;
		v8m_reallocarray;
		v8m_malloc_usable_size;
		v8m_aligned_alloc;
		v8m_posix_memalign;
		v8m_memalign;
		v8m_valloc;
		v8m_pvalloc;
		v8m_set_option;
		v8m_get_option;
		v8m_get_stats;
		v8m_dump_stats;
		v8m_set_oom_handler;
		v8m_set_soft_limit;
		v8m_get_soft_limit;
		v8m_is_valid_ptr;
		v8m_ptr_info;

		v8m_get_huge_stats;
		v8m_get_thread_stats;
		v8m_get_size_class_histogram;
		v8m_get_slab_class_breakdown;
		v8m_get_slab_class_breakdown_lifetime;
		v8m_get_arch_info;
		v8m_init_thread;
		v8m_release_thread;
		v8m_option_name;
		v8m_install_size_class_table;
		v8m_size_class_to_bytes;
		v8m_get_lifetime_stats;
		v8m_estimate_lifetime;
		v8m_get_numa_balance;
		v8m_get_frag_metrics;
		v8m_count_vmas;
		v8m_signal_safe_alloc;
		v8m_purge;
		v8m_purge_thread;

		v8m_mallinfo;
		v8m_mallinfo2;
		v8m_malloc_stats;
		v8m_malloc_info;
		v8m_mallopt;
		v8m_malloc_trim;

		malloc;
		free;
		calloc;
		realloc;
		reallocarray;
		malloc_usable_size;
		aligned_alloc;
		posix_memalign;
		memalign;
		valloc;
		pvalloc;

		mallinfo;
		mallinfo2;
		mallopt;
		malloc_stats;
		malloc_info;
		malloc_trim;

		__libc_malloc;
		__libc_free;
		__libc_calloc;
		__libc_realloc;
		__libc_memalign;
		__libc_valloc;
		__libc_pvalloc;

		/* C++ Itanium-ABI mangled names: non-throwing
		 * variants of operator new / delete. The throwing
		 * forms (_Znwm, _Znam, _ZnwmSt11align_val_t,
		 * _ZnamSt11align_val_t) stay in libstdc++ because we
		 * can't construct std::bad_alloc from C; libstdc++'s
		 * implementations call malloc internally and pick up
		 * v8malloc transparently. */
		_ZdlPv;
		_ZdaPv;
		_ZdlPvm;
		_ZdaPvm;
		_ZdlPvSt11align_val_t;
		_ZdaPvSt11align_val_t;
		_ZdlPvmSt11align_val_t;
		_ZdaPvmSt11align_val_t;
		_ZnwmRKSt9nothrow_t;
		_ZnamRKSt9nothrow_t;
		_ZdlPvRKSt9nothrow_t;
		_ZdaPvRKSt9nothrow_t;
		_ZnwmSt11align_val_tRKSt9nothrow_t;
		_ZnamSt11align_val_tRKSt9nothrow_t;
		_ZdlPvSt11align_val_tRKSt9nothrow_t;
		_ZdaPvSt11align_val_tRKSt9nothrow_t;
	local:
		*;
};
